""""
Create a complete OpenFOAM 10 (Foundation) case for a 3D Bernard cell
(Rayleigh-Benard convection) run with the buoyantFoam solver.

Domain: 9 m (x) x 1 m (y) x 2 m (z)
 - bottom wall (y = 0): hot,  T = 310 K
 - top wall    (y = 1): cold, T = 290 K
 - side walls: adiabatic, no-slip
 - gravity: (0 -9.81 0)

Only files are written; no OpenFOAM commands are executed here.
Run with:  chmod +x Allrun && ./Allrun
"""

import os


def w(path, content):
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "w") as f:
        f.write(content)


def hdr(obj, cls="dictionary"):
    return (
        "FoamFile\n"
        "{\n"
        "    version     2.0;\n"
        "    format      ascii;\n"
        "    class       " + cls + ";\n"
        "    object      " + obj + ";\n"
        "}\n"
    )


def field(obj, cls, dims, internal, boundary):
    return (
        hdr(obj, cls)
        + "\ndimensions      [" + dims + "];\n\n"
        + "internalField   uniform " + internal + ";\n\n"
        + "boundaryField\n{\n" + boundary + "}\n"
    )


